(5850714, 851706, 65234, '<td valign="top">The obvious texture on the winter coat really helps emphasize the cold concept.</td>', 'The obvious texture on the winter coat really helps emphasize the cold concept.', '2010-02-03 10:08:58.000000', NULL, 1),
(5850716, 850786, 65234, '<td valign="top">Great image for this challenge.  The horse looks very patient, I must say.  Like he had to stand there and wait for enough snow to sccumulate for you to take the picture ;-)</td>', 'Great image for this challenge.  The horse looks very patient, I must say.  Like he had to stand there and wait for enough snow to sccumulate for you to take the picture ;-)', '2010-02-03 10:10:57.000000', NULL, 1),
