(5861022, 850755, 50034, '<td valign="top">Great Stop-Action Shot!  :)</td>', 'Great Stop-Action Shot!  :)', '2010-02-09 23:10:20.000000', NULL, 1),
(5861024, 851588, 67697, '<td valign="top">Beautiful scene.  I like that you managed to keep the white branches from blending into the light background.  Love the contrasts on the tree.</td>', 'Beautiful scene.  I like that you managed to keep the white branches from blending into the light background.  Love the contrasts on the tree.', '2010-02-09 23:10:52.000000', NULL, 1),
(5861025, 851708, 50034, '<td valign="top">I always wondered where they got those bags of ice at the convenience stores...  ;)</td>', 'I always wondered where they got those bags of ice at the convenience stores...  ;)', '2010-02-09 23:11:22.000000', NULL, 1),
(5861027, 851748, 50034, '<td valign="top">Great!  :)</td>', 'Great!  :)', '2010-02-09 23:12:09.000000', NULL, 1),
(5861029, 851243, 67697, '<td valign="top">Great capture of the snowflake designs.  The contrast and clarity is awesome.  Love the icy blue color.</td>', 'Great capture of the snowflake designs.  The contrast and clarity is awesome.  Love the icy blue color.', '2010-02-09 23:12:57.000000', NULL, 1),
(5861030, 850784, 50034, '<td valign="top">Soft-Focus, but a really sweet smile!  THAT gives this photo its appeal.  :)</td>', 'Soft-Focus, but a really sweet smile!  THAT gives this photo its appeal.  :)', '2010-02-09 23:13:28.000000', NULL, 1),
(5861031, 851762, 50034, '<td valign="top">Excellent!  Nearly HDR!  Great Work!  :)</td>', 'Excellent!  Nearly HDR!  Great Work!  :)', '2010-02-09 23:14:03.000000', NULL, 1),
(5861033, 851205, 50034, '<td valign="top">Crossing the "frozen" lake a little prematurely, aren''t we?  ;)</td>', 'Crossing the "frozen" lake a little prematurely, aren''t we?  ;)', '2010-02-09 23:15:49.000000', NULL, 1),
(5861034, 850634, 50034, '<td valign="top">Most Unique!  Great Work!  :)</td>', 'Most Unique!  Great Work!  :)', '2010-02-09 23:16:33.000000', NULL, 1),
(5861040, 850645, 67697, '<td valign="top">The expression on her face says it all.  I like the flash of sun.  It''s like that little hope of spring is hanging on and ready to roll.</td>', 'The expression on her face says it all.  I like the flash of sun.  It''s like that little hope of spring is hanging on and ready to roll.', '2010-02-09 23:20:37.000000', NULL, 1),
(5861042, 850786, 67697, '<td valign="top">Beautiful capture.  Love the details on the face.  Too bad the poor dear is covered in so much snow :(</td>', 'Beautiful capture.  Love the details on the face.  Too bad the poor dear is covered in so much snow :(', '2010-02-09 23:22:35.000000', NULL, 1),
(5861044, 850887, 67697, '<td valign="top">I like it for the quirkiness.  Odd and yet fun...</td>', 'I like it for the quirkiness.  Odd and yet fun...', '2010-02-09 23:23:16.000000', NULL, 1),
(5861048, 850838, 67697, '<td valign="top">Great candid.  Not ready for that big bite of cold stuff, huh?  Love the spot focus.</td>', 'Great candid.  Not ready for that big bite of cold stuff, huh?  Love the spot focus.', '2010-02-09 23:27:12.000000', NULL, 1),
(5861049, 851416, 67697, '<td valign="top">I like how you captured the blowing snow and the light that is falling on the drifts.</td>', 'I like how you captured the blowing snow and the light that is falling on the drifts.', '2010-02-09 23:27:40.000000', NULL, 1),
(5861051, 851721, 112347, '<td valign="top">Love this as it says cold with an !!!!</td>', 'Love this as it says cold with an !!!!', '2010-02-09 23:29:24.000000', NULL, 1),
(5861052, 851596, 112347, '<td valign="top">love this shot.</td>', 'love this shot.', '2010-02-09 23:29:26.000000', NULL, 1),
(5861053, 851203, 112347, '<td valign="top">I love the waves splashing against the frozen.  I feel that the tree was cut off and shouldn''t have been. could have cut out some of the lower beach to keep the top of the tree.</td>', 'I love the waves splashing against the frozen.  I feel that the tree was cut off and shouldn''t have been. could have cut out some of the lower beach to keep the top of the tree.', '2010-02-09 23:29:35.000000', NULL, 1),
(5861056, 851714, 67697, '<td valign="top">Love all the different points of reflection.  The glittery icicle is beautiful.</td>', 'Love all the different points of reflection.  The glittery icicle is beautiful.', '2010-02-09 23:30:24.000000', NULL, 1),
(5861058, 850628, 67697, '<td valign="top">To see something like this in person has to be quite breathtaking.  The clouds floating around the scene are quite dreamy.  Beautiful scene!</td>', 'To see something like this in person has to be quite breathtaking.  The clouds floating around the scene are quite dreamy.  Beautiful scene!', '2010-02-09 23:31:29.000000', NULL, 1),
